def page(n,d):
    L=[f"---\ntitle: \"{n}주 — {d['title']}\"\nlayout: default\n---",
       f"[← 수업 홈](../) · [자세한 안내문 →](handout.html) · [제출 폼]({FORM})","",
       f"# {int(n)}주 — {d['title']}","",
       "## 질문", d['q'], "",
       "## 읽을 것"]
    L += [f"- {r}" for r in d['read']]
    if any("묶음" in r for r in d['read']): L.append(f"- 강독 논문 묶음 PDF: <{PDF}> · [쪽 지도](../common/readings.html)")
    L += ["", "## 수업의 순서 (100분 × 2회)"] + [f"- {p}" for p in d['plan']]
    if d.get('data'): L += ["", "## 이 주의 자료(교수 제공)"] + [f"- {x}" for x in d['data']]
    if d.get('lab'): L += ["", "## 실습 방안"] + [f"- {x}" for x in d['lab']]
    L += ["", "## 과제"] + [f"- {t}" for t in d['task']]
    L += ["", "세부 진행·개념·주요 발췌·더 읽을 거리·참고문헌은 [자세한 안내문](handout.html)에.", ""]
    import re
    out="\n".join(L)
    out=re.sub(r"`((?:\.\./|data/|excerpts)[^`]*)`", lambda m: f"[{m.group(1)}]({m.group(1)})", out)
    return out

for n,d in W.items():
    os.makedirs(f"{DOCS}/week{n}", exist_ok=True)
    open(f"{DOCS}/week{n}/index.md","w",encoding="utf-8").write(page(n,d))
    print("ok",n)
